import * as React from "react"

// Generated by `npx shadcn@latest add sidebar`, then rewritten on `useSyncExternalStore`: the
// generated version set state inside an effect, which `react-hooks/set-state-in-effect` rejects.
// Same contract: false on the server and before hydration, then whether the viewport is under 768 px.

const MOBILE_BREAKPOINT = 768

function subscribe(onChange: () => void) {
  const mql = window.matchMedia(`(max-width: ${MOBILE_BREAKPOINT - 1}px)`)
  mql.addEventListener("change", onChange)
  return () => mql.removeEventListener("change", onChange)
}

const isMobileViewport = () => window.innerWidth < MOBILE_BREAKPOINT
const onServer = () => false

export function useIsMobile() {
  return React.useSyncExternalStore(subscribe, isMobileViewport, onServer)
}
